#[verus]
pub fn solve(input: Vec<(i8, i8)>) -> Vec<i8> {
    // Ensure that the input vector is not empty
    assert!(input.len() > 0);
    
    // Initialize the output vector with the same length as input
    let mut output: Vec<i8> = vec![0; input.len()];

    // Iterate over each query in the input
    for (i, (a, b)) in input.iter().enumerate() {
        // Ensure that a and b are positive integers
        assert!(*a >= 1);
        assert!(*b >= 1);

        // Calculate the minimum number of moves
        output[i] = min_moves(*a, *b);
    }

    output
}

// Function to calculate the minimum moves from a to b
#[verus]
fn min_moves(a: i8, b: i8) -> i8 {
    // If a is already equal to b, no moves are needed
    if a == b {
        return 0;
    }

    // Calculate the difference
    let diff = (b - a).abs();

    // If the difference is odd, we need at least one move
    if diff % 2 == 1 {
        // We can reach b in one move by adding the odd difference
        return 1;
    } else {
        // If the difference is even, we can reach b in two moves
        // (one odd increase and one even decrease)
        return 2;
    }
}